     3|// ---------------------------------------------------------------------------
     4|// Zobrist hashing — 15×15×2 random 32-bit pairs (simulating 64-bit keys)
     5|// Index: player 0 = index 0..449, player 1 = index 450..899
     6|// ---------------------------------------------------------------------------
     7|const ZOBRIST_LO = new Uint32Array(BOARD_SIZE * BOARD_SIZE * 2)
     8|const ZOBRIST_HI = new Uint32Array(BOARD_SIZE * BOARD_SIZE * 2)
     9|;(function initZobrist() {
    10|  for (let i = 0; i < ZOBRIST_LO.length; i++) {
    11|    ZOBRIST_LO[i] = (Math.random() * 0x100000000) >>> 0
    12|    ZOBRIST_HI[i] = (Math.random() * 0x100000000) >>> 0
    13|  }
    14|})()
    15|
    16|// player: 1 or 2  →  offset 0 or 450
    17|function _zobristIdx(r, c, player) {
    18|  return (player - 1) * BOARD_SIZE * BOARD_SIZE + r * BOARD_SIZE + c
    19|}
    20|
    21|export function computeHash(board) {
    22|  let lo = 0, hi = 0
    23|  for (let r = 0; r < BOARD_SIZE; r++) {
    24|    for (let c = 0; c < BOARD_SIZE; c++) {
    25|      const p = board[r][c]
    26|      if (p !== 0) {
    27|        const idx = _zobristIdx(r, c, p)
    28|        lo ^= ZOBRIST_LO[idx]
    29|        hi ^= ZOBRIST_HI[idx]
    30|      }
    31|    }
    32|  }
    33|  return [lo, hi]
    34|}
    35|
    36|// Returns a NEW hash array — does not mutate the input array.
    37|export function updateHash(hash, r, c, player) {
    38|  const idx = _zobristIdx(r, c, player)
    39|  return [hash[0] ^ ZOBRIST_LO[idx], hash[1] ^ ZOBRIST_HI[idx]]
    40|}
