    46|export async function computeBestMoveAsync(board, game, difficulty, aiParams) {
    47|  return new Promise((resolve, reject) => {
    48|    if (typeof Worker !== 'undefined') {
    49|      const worker = new Worker(new URL('./ai.worker.js', import.meta.url), { type: 'module' })
    50|      worker.postMessage({ id: 'root', game, board, difficulty, aiParams })
    51|      
    52|      const timeout = setTimeout(() => {
    53|        worker.terminate()
    54|        reject(new Error('AI computation timeout'))
    55|      }, 10000)
    56|      
    57|      worker.onmessage = (e) => {
    58|        clearTimeout(timeout)
    59|        worker.terminate()
    60|        if (e.data.error) reject(new Error(e.data.error))
    61|        else resolve(e.data.move)
    62|      }
    63|      
    64|      worker.onerror = (err) => {
    65|        clearTimeout(timeout)
    66|        worker.terminate()
    67|        reject(err)
