    95|// ---------------------------------------------------------------------------
    96|// Traverse one ray from (r, c) in direction (dr, dc) and return the number of
    97|// consecutive player stones and whether the ray ends on an open cell.
    98|// ---------------------------------------------------------------------------
    99|function countDirection(board, r, c, dr, dc, player) {
   100|  let count = 0
   101|  let openEnd = 0
   102|  for (let d = 1; d <= 4; d++) {
   103|    const nr = r + dr * d, nc = c + dc * d
   104|    if (nr < 0 || nr >= BOARD_SIZE || nc < 0 || nc >= BOARD_SIZE) break
   105|    if (board[nr][nc] === player) count++
   106|    else { if (board[nr][nc] === 0) openEnd = 1; break }
   107|  }
   108|  return { count, openEnd }
   109|}
   110|
   111|export function evaluatePosition(board, r, c, player) {
   112|  const dirs = [[0, 1], [1, 0], [1, 1], [1, -1]]
   113|  let total = 0
   114|
   115|  for (const [dr, dc] of dirs) {
   116|    const fwd = countDirection(board, r, c, dr, dc, player)
   117|    const bwd = countDirection(board, r, c, -dr, -dc, player)
   118|    const count = 1 + fwd.count + bwd.count
   119|    const openEnds = fwd.openEnd + bwd.openEnd
   120|
   121|    if (count >= 5) total += SCORE.FIVE
   122|    else if (count === 4) total += openEnds === 2 ? SCORE.OPEN_FOUR : SCORE.HALF_FOUR
   123|    else if (count === 3) total += openEnds === 2 ? SCORE.OPEN_THREE : SCORE.HALF_THREE
   124|    else if (count === 2) total += openEnds === 2 ? SCORE.OPEN_TWO : SCORE.HALF_TWO
   125|    else total += SCORE.ONE
   126|  }
   127|
   128|  return total
