   133|export function boardScore(board, ai, human, style = DEFAULT_STYLE) {
   134|  let score = 0
   135|  for (let r = 0; r < BOARD_SIZE; r++) {
   136|    for (let c = 0; c < BOARD_SIZE; c++) {
   137|      if (board[r][c] === ai) {
   138|        let s = evaluatePosition(board, r, c, ai) * style.attack
   139|        if (style.center > 0) {
   140|          const dist = Math.max(Math.abs(r - 7), Math.abs(c - 7))
   141|          s += (7 - dist) * style.center * 2
   142|        }
   143|        score += s
   144|      } else if (board[r][c] === human) {
   145|        score -= evaluatePosition(board, r, c, human) * style.defense
   146|      }
   147|    }
   148|  }
   149|  return score
   150|}
   151|
   152|export function getCandidates(board, limit = null) {
   153|  const candidates = new Set()
   154|  const range = 2
   155|  for (let r = 0; r < BOARD_SIZE; r++) {
   156|    for (let c = 0; c < BOARD_SIZE; c++) {
   157|      if (board[r][c] !== 0) {
   158|        for (let dr = -range; dr <= range; dr++) {
   159|          for (let dc = -range; dc <= range; dc++) {
   160|            const nr = r + dr, nc = c + dc
   161|            if (nr >= 0 && nr < BOARD_SIZE && nc >= 0 && nc < BOARD_SIZE && board[nr][nc] === 0) {
   162|              candidates.add(nr * BOARD_SIZE + nc)
   163|            }
   164|          }
   165|        }
   166|      }
   167|    }
   168|  }
   169|  if (candidates.size === 0) candidates.add(7 * BOARD_SIZE + 7)
   170|  return Array.from(candidates)
   171|    .map((idx) => {
   172|      const r = Math.floor(idx / BOARD_SIZE), c = idx % BOARD_SIZE
   173|      const score = Math.max(evaluatePosition(board, r, c, 1), evaluatePosition(board, r, c, 2))
   174|      return { r, c, score }
   175|    })
   176|    .sort((a, b) => b.score - a.score)
   177|    .slice(0, limit ?? Number.POSITIVE_INFINITY)
   178|    .map(({ r, c }) => ({ r, c }))
   179|}
   180|
   181|export function checkWinBoard(board, r, c, player) {
   182|  const dirs = [[0, 1], [1, 0], [1, 1], [1, -1]]
   183|  for (const [dr, dc] of dirs) {
   184|    let count = 1
   185|    for (let d = 1; d < 5; d++) {
   186|      const nr = r + dr * d, nc = c + dc * d
   187|      if (nr >= 0 && nr < BOARD_SIZE && nc >= 0 && nc < BOARD_SIZE && board[nr][nc] === player) count++
   188|      else break
   189|    }
   190|    for (let d = 1; d < 5; d++) {
   191|      const nr = r - dr * d, nc = c - dc * d
   192|      if (nr >= 0 && nr < BOARD_SIZE && nc >= 0 && nc < BOARD_SIZE && board[nr][nc] === player) count++
   193|      else break
   194|    }
   195|    if (count >= 5) return true
   196|  }
   197|  return false
   198|}
