   200|const TIMEOUT = Symbol('AI_SEARCH_TIMEOUT')
   201|function nowMs() {
   202|  return typeof performance !== 'undefined' ? performance.now() : Date.now()
   203|}
   204|
   205|function minimax(board, depth, alpha, beta, maximizing, ai, human, style, hash, endTimeMs) {
   206|  if (endTimeMs !== Infinity && nowMs() >= endTimeMs) throw TIMEOUT
   207|  // ---------------------------------------------------------------------------
   208|  // Transposition table lookup
   209|  // ---------------------------------------------------------------------------
   210|  const key = hashKey(hash)
   211|  const ttEntry = transpositionTable.get(key)
   212|  if (ttEntry !== undefined && ttEntry.depth >= depth) {
   213|    if (ttEntry.flag === 'exact') return ttEntry.score
   214|    if (ttEntry.flag === 'lower') alpha = Math.max(alpha, ttEntry.score)
   215|    else if (ttEntry.flag === 'upper') beta = Math.min(beta, ttEntry.score)
   216|    if (alpha >= beta) return ttEntry.score
   217|  }
   218|
   219|  if (depth === 0) {
   220|    const score = boardScore(board, ai, human, style)
   221|    // Store leaf node as exact
   222|    _ttStore(key, depth, score, 'exact')
   223|    return score
   224|  }
   225|
   226|  // Candidate beam-width: keep branching factor under control as depth increases.
   227|  const beam =
   228|    depth >= 3 ? 16
   229|      : depth === 2 ? 20
   230|        : depth === 1 ? 24
   231|          : 0
   232|  const candidates = beam > 0 ? getCandidates(board, beam) : getCandidates(board)
   233|  const originalAlpha = alpha
   234|
   235|  if (maximizing) {
   236|    let best = -Infinity
   237|    for (const { r, c } of candidates) {
   238|      board[r][c] = ai
   239|      try {
   240|        const newHash = updateHash(hash, r, c, ai)
   241|        if (checkWinBoard(board, r, c, ai)) return SCORE.FIVE * 10
   242|        const val = minimax(board, depth - 1, alpha, beta, false, ai, human, style, newHash, endTimeMs)
   243|        best = Math.max(best, val)
   244|        alpha = Math.max(alpha, best)
   245|        if (beta <= alpha) break
   246|      } finally {
   247|        board[r][c] = 0
   248|      }
   249|    }
   250|    const flag = best <= originalAlpha ? 'upper' : best >= beta ? 'lower' : 'exact'
   251|    _ttStore(key, depth, best, flag)
   252|    return best
   253|  } else {
   254|    let best = Infinity
   255|    const originalBeta = beta
   256|    for (const { r, c } of candidates) {
   257|      board[r][c] = human
   258|      try {
   259|        const newHash = updateHash(hash, r, c, human)
   260|        if (checkWinBoard(board, r, c, human)) return -SCORE.FIVE * 10
   261|        const val = minimax(board, depth - 1, alpha, beta, true, ai, human, style, newHash, endTimeMs)
   262|        best = Math.min(best, val)
   263|        beta = Math.min(beta, best)
   264|        if (beta <= alpha) break
   265|      } finally {
   266|        board[r][c] = 0
   267|      }
   268|    }
   269|    const flag = best >= originalBeta ? 'lower' : best <= alpha ? 'upper' : 'exact'
   270|    _ttStore(key, depth, best, flag)
   271|    return best
   272|  }
   273|}
   274|
   275|function _ttStore(key, depth, score, flag) {
   276|  if (transpositionTable.size >= TT_LIMIT) transpositionTable = new Map()
   277|  transpositionTable.set(key, { depth, score, flag })
   278|}
