   280|export function getBestMove(board, difficulty, style = DEFAULT_STYLE, aiParams = {}) {
   281|  const ai = 2, human = 1
   282|  const maxDepth = DIFFICULTY_CONFIG[difficulty]?.depth ?? 3
   283|  const candidates = getCandidates(board)
   284|
   285|  const timeLimitMs = aiParams?.timeLimitMs ?? 2000
   286|  const endTimeMs = timeLimitMs > 0 ? nowMs() + timeLimitMs : Infinity
   287|
   288|  // Immediate win
   289|  for (const { r, c } of candidates) {
   290|    board[r][c] = ai
   291|    try {
   292|      if (checkWinBoard(board, r, c, ai)) return { r, c }
   293|    } finally {
   294|      board[r][c] = 0
   295|    }
   296|  }
   297|  // Block opponent
   298|  for (const { r, c } of candidates) {
   299|    board[r][c] = human
   300|    try {
   301|      if (checkWinBoard(board, r, c, human)) return { r, c }
   302|    } finally {
   303|      board[r][c] = 0
   304|    }
   305|  }
   306|
   307|  if (difficulty === 'easy') {
   308|    let best = -Infinity, bestMove = null
   309|    for (const { r, c } of candidates) {
   310|      board[r][c] = ai
   311|      let s = evaluatePosition(board, r, c, ai) * style.attack
   312|            - evaluatePosition(board, r, c, human) * style.defense
   313|      if (style.noise > 0) s += (Math.random() - 0.5) * style.noise * SCORE.OPEN_THREE
   314|      board[r][c] = 0
   315|      if (s > best) { best = s; bestMove = { r, c } }
   316|    }
   317|    return bestMove
   318|  }
   319|
   320|  const scored = candidates
   321|    .map(({ r, c }) => {
   322|      board[r][c] = ai
   323|      let s = evaluatePosition(board, r, c, ai)
   324|      if (style.noise > 0) s += (Math.random() - 0.5) * style.noise * SCORE.OPEN_THREE
   325|      board[r][c] = 0
   326|      return { r, c, s }
   327|    })
   328|    .sort((a, b) => b.s - a.s)
   329|    .slice(0, 26)
   330|
   331|  // Compute initial board hash once before the search loop
   332|  const rootHash = computeHash(board)
   333|
   334|  let bestMove = null
   335|  let lastCompletedMove = null
   336|
   337|  for (let depth = 1; depth <= maxDepth; depth++) {
   338|    if (endTimeMs !== Infinity && nowMs() >= endTimeMs) break
   339|    let best = -Infinity
   340|    let curBestMove = null
   341|
   342|    // PV move first: increases alpha-beta cutoffs for deeper iterations.
   343|    const pv = lastCompletedMove
   344|    const ordered = pv
   345|      ? [...scored].sort((a, b) => (a.r === pv.r && a.c === pv.c) ? -1 : (b.r === pv.r && b.c === pv.c) ? 1 : 0)
   346|      : scored
   347|
   348|    try {
   349|      for (const { r, c } of ordered) {
   350|        if (endTimeMs !== Infinity && nowMs() >= endTimeMs) throw TIMEOUT
   351|        board[r][c] = ai
   352|        try {
   353|          const childHash = updateHash(rootHash, r, c, ai)
   354|          const val = minimax(board, depth - 1, -Infinity, Infinity, false, ai, human, style, childHash, endTimeMs)
   355|          if (val > best) { best = val; curBestMove = { r, c } }
   356|        } finally {
   357|          board[r][c] = 0
   358|        }
   359|      }
   360|      bestMove = curBestMove
   361|      lastCompletedMove = curBestMove
   362|    } catch (err) {
   363|      if (err !== TIMEOUT) throw err
   364|      break
   365|    }
   366|  }
   367|
   368|  return bestMove ?? lastCompletedMove ?? scored[0]
   369|}
